40:   const cellH = Math.max(34, Math.min(compact ? 65 : 94, cellW * (compact ? 1.0 : .92), (height - gridTop - 34) / 5));
41:   const boardW = cellW * 9;
42:   const boardH = cellH * 5;
43:   return {
44:     compact, short, cellW, cellH, boardW, boardH,
45:     left: (width - boardW) / 2,
46:     top: gridTop,
47:     card: compact ? { x: 12, y: short ? 26 : 34, w: 154, h: 91 } : { x: 34, y: short ? 10 : 80, w: 220, h: 122 },
