145:   ctx.shadowColor = "rgba(54,58,27,.26)"; ctx.shadowBlur = 12; ctx.shadowOffsetY = 5;
146:   fillRound(ctx, x, y, w, h, 13, "#59401f", selected ? "#fff17a" : "#543c21", selected ? 4 : 2);
147:   ctx.shadowColor = "transparent";
148:   const panel = ctx.createLinearGradient(x, y, x + w, y + h);
149:   panel.addColorStop(0, "#f6df9d"); panel.addColorStop(.48, "#e9c574"); panel.addColorStop(1, "#c69148");
150:   fillRound(ctx, x + 4, y + 4, w - 8, h - 8, 10, panel, "#f9e9b7", 1.2);
151:   const artSize = layout.compact ? h * .72 : h * .73;
152:   const artX = x + (layout.compact ? 8 : 13);
153:   const artY = y + h - (layout.compact ? 8 : 12);
154:   fillRound(ctx, x + 8, y + 9, artSize + 5, h - 18, 8, "#91b951", "#8c682e", 1.3);
