157:   garden.addColorStop(0, "#b8d77b"); garden.addColorStop(1, "#76a849");
158:   ctx.fillStyle = garden; ctx.fillRect(x + 8, y + 9, artSize + 5, h - 18);
159:   drawPeashooter(ctx, artX + artSize * .54, artY - 5, artSize * .85, now * .7);
