164:   ctx.fillText(layout.compact ? "LANZA" : "LANZAGUISANTES", tx, y + (layout.compact ? 24 : 30));
165:   if (!layout.compact) {
166:     ctx.fillStyle = "#76552c"; ctx.font = "700 10px Trebuchet MS, sans-serif";
