214: function updateCombat(now) {
215:   const { left, top, cellW, cellH } = layout;
216:   const targets = [...enemies.enemies.values()].filter((enemy) => enemy.alive);
217:   for (const plant of game.plants.values()) {
218:     if (!plant.alive || !plant.exists) {
219:       plant.attackState = "IDLE";
220:       plant.targetId = null;
221:       continue;
222:     }
223:     plant.boardX = (plant.worldPosition.x - left) / cellW;
224:     const target = targets
225:       .filter((enemy) => enemy.row === plant.row && enemy.x > plant.boardX)
226:       .sort((a, b) => a.x - b.x)[0] ?? null;
227:     plant.targetId = target?.id ?? null;
228:     if (!target) {
229:       plant.attackState = "IDLE";
230:       continue;
231:     }
232:     if (now >= plant.nextAttackAt) {
233:       const plantSize = cellW * .83;
234:       projectiles.spawn({
235:         x: plant.worldPosition.x + plantSize * .39,
236:         y: plant.worldPosition.y - plantSize * .565,
237:         row: plant.row,
238:         damage: plant.damage,
239:         speed: plant.projectileSpeed,
240:         ownerId: plant.id,
241:       }, now);
242:       plant.attackState = "SHOOTING";
243:       plant.attackStartedAt = now;
244:       plant.nextAttackAt = now + plant.attackIntervalMs;
245:     } else {
246:       plant.attackState = now - plant.attackStartedAt < 180 ? "SHOOTING" : "AIMING";
247:     }
248:   }
249:   projectiles.update(now, enemies.enemies, { ...layout, width, left, top, cellW, cellH }, enemies);
250: }
