267: function drawBoard(now) {
268:   const { left, top, cellW, cellH, boardW, boardH } = layout;
269:   ctx.save();
270:   ctx.shadowColor = "rgba(46,66,34,.28)"; ctx.shadowBlur = 16; ctx.shadowOffsetY = 8;
271:   fillRound(ctx, left - 12, top - 12, boardW + 24, boardH + 24, 16, "#a96e39", "#754a2c", 3);
272:   ctx.shadowColor = "transparent";
273:   const frame = ctx.createLinearGradient(0, top - 12, 0, top + boardH + 12);
274:   frame.addColorStop(0, "#d49a55"); frame.addColorStop(.5, "#bd7f41"); frame.addColorStop(1, "#99602f");
275:   fillRound(ctx, left - 8, top - 8, boardW + 16, boardH + 16, 11, frame, "#e4b46f", 2);
276:   // These cells are the sole source of row/column hit-testing and occupancy visuals.
277:   for (let row = 0; row < game.rows; row++) {
278:     for (let column = 0; column < game.columns; column++) {
279:       const x = left + column * cellW; const y = top + row * cellH;
280:       const plant = game.getAt(row, column);
281:       const hovered = state.hoveredCell?.row === row && state.hoveredCell?.column === column;
282:       const shade = (row + column) % 2 === 0;
283:       fillRound(ctx, x + 1, y + 1, cellW - 2, cellH - 2, 4, shade ? "#88c750" : "#7fbd48", "rgba(49,101,39,.33)", 1);
284:       ctx.strokeStyle = "rgba(238,255,177,.15)"; ctx.lineWidth = 1;
285:       ctx.beginPath(); ctx.moveTo(x + 6, y + cellH - 6); ctx.lineTo(x + cellW - 7, y + 7); ctx.stroke();
286:       if (state.selected) {
287:         ctx.fillStyle = plant ? "rgba(193,61,44,.20)" : "rgba(220,255,161,.15)";
288:         ctx.fillRect(x + 2, y + 2, cellW - 4, cellH - 4);
289:         ctx.strokeStyle = plant ? "rgba(163,48,38,.68)" : "rgba(242,255,193,.8)";
290:         ctx.lineWidth = plant ? 2 : 1.3; ctx.setLineDash(plant ? [4, 3] : [5, 5]);
291:         ctx.strokeRect(x + 4, y + 4, cellW - 8, cellH - 8); ctx.setLineDash([]);
292:       }
293:       if (hovered) {
294:         ctx.strokeStyle = state.selected && plant ? "#cf5141" : "#fff39a";
295:         ctx.lineWidth = 3; ctx.strokeRect(x + 3, y + 3, cellW - 6, cellH - 6);
296:       }
297:     }
298:   }
299:   ctx.restore();
300: 
301:   // Plant data is rendered independently from occupancy and placement rules.
302:   for (const plant of game.plants.values()) {
303:     if (!plant.exists) continue;
304:     const target = plant.targetId ? enemies.get(plant.targetId) : null;
305:     const plantSize = cellW * .83;
306:     const muzzleX = plant.worldPosition.x + plantSize * .39;
307:     const muzzleY = plant.worldPosition.y - plantSize * .565;
308:     const targetX = target ? left + target.x * cellW : muzzleX + cellW;
309:     const targetY = target ? top + (target.row + .88) * cellH - cellH * .96 * .55 : muzzleY;
310:     drawPeashooter(ctx, plant.worldPosition.x, plant.worldPosition.y, plantSize, now, {
311:       age: now - plant.animationStartedAt,
312:       disappearing: plant.animationState === "disappearing",
313:       attackState: plant.attackState,
314:       aimAngle: plant.targetId ? Math.atan2(targetY - muzzleY, targetX - muzzleX) : 0,
315:     });
316:     if (plant.alive) drawHealthBar(plant.worldPosition.x - cellW * .2, plant.worldPosition.y - plantSize * .96, cellW * .4, plant.health, plant.maxHealth);
317:   }
318:   // Enemies are drawn above plants so a clone approaching an obstacle stays legible.
319:   for (const enemy of enemies.enemies.values()) {
320:     if (enemy.state === "DEAD") continue;
321:     const enemyX = left + enemy.x * cellW;
322:     const enemyY = top + (enemy.row + .88) * cellH;
323:     drawBasicClone(ctx, enemyX, enemyY, cellH * .96, now, enemy);
324:     drawHealthBar(enemyX - cellH * .21, enemyY - cellH * .98, cellH * .42, enemy.health, enemy.maxHealth);
325:     if (enemy.state === "DETECTING" || enemy.state === "ATTACKING") {
326:       const label = enemy.state === "DETECTING" ? "¡PLANTA!" : "DETENIDO";
327:       ctx.save();
328:       ctx.font = `900 ${layout.compact ? 8 : 9}px Trebuchet MS, sans-serif`;
329:       ctx.textAlign = "center"; ctx.textBaseline = "middle";
330:       const labelW = ctx.measureText(label).width + 12;
331:       fillRound(ctx, enemyX - labelW / 2, enemyY - cellH * .99, labelW, 16, 8,
332:         enemy.state === "ATTACKING" ? "rgba(116,65,48,.9)" : "rgba(69,83,47,.88)", "rgba(255,244,206,.8)", 1);
333:       ctx.fillStyle = "#fff4d5"; ctx.fillText(label, enemyX, enemyY - cellH * .99 + 8);
334:       ctx.restore();
335:     }
336:   }
337:   for (const corpse of enemies.corpses.values()) {
338:     const corpseX = left + corpse.x * cellW;
339:     const corpseY = top + (corpse.row + .88) * cellH;
340:     drawBasicClone(ctx, corpseX, corpseY, cellH * .96, now, corpse);
341:   }
342:   for (const projectile of projectiles.projectiles) drawProjectile(projectile, now);
343:   const cell = state.hoveredCell;
344:   if (state.selected && cell) {
345:     const occupant = game.getAt(cell.row, cell.column);
346:     const centerX = left + (cell.column + .5) * cellW;
347:     const baseline = top + (cell.row + .87) * cellH;
348:     if (!occupant && game.sun >= PLANT_TYPES[state.selected].cost && game.cooldownRemaining(state.selected, now) <= 0) {
349:       drawPeashooter(ctx, centerX, baseline, cellW * .83, now, { ghost: true });
350:     } else if (occupant) {
351:       const markY = top + (cell.row + .2) * cellH;
352:       ctx.save(); ctx.strokeStyle = "rgba(143,43,36,.9)"; ctx.lineWidth = 3;
353:       ctx.beginPath(); ctx.arc(centerX, markY, Math.max(8, cellW * .1), 0, Math.PI * 2); ctx.stroke();
354:       ctx.beginPath(); ctx.moveTo(centerX - 4, markY - 4); ctx.lineTo(centerX + 4, markY + 4);
355:       ctx.moveTo(centerX + 4, markY - 4); ctx.lineTo(centerX - 4, markY + 4); ctx.stroke(); ctx.restore();
356:     }
357:   }
358: }
