468: function updatePointer(point) {
469:   pointer.x = point.x; pointer.y = point.y; pointer.inside = true;
470:   pointer.hoveredSun = null;
471:   const liveSuns = [...suns.suns.values()];
472:   for (let i = liveSuns.length - 1; i >= 0; i--) {
473:     const sun = liveSuns[i];
474:     if (sun.collected || sun.expired) continue;
475:     const dx = point.x - sun.x; const dy = point.y - sun.y;
476:     if (dx * dx + dy * dy <= (SUN_CONFIG.radius + 11) ** 2) { pointer.hoveredSun = sun.id; break; }
477:   }
478:   canvas.style.cursor = pointer.hoveredSun ? "pointer" : "crosshair";
479:   const { left, top, cellW, cellH, boardW, boardH } = layout;
480:   if (point.x >= left && point.x < left + boardW && point.y >= top && point.y < top + boardH) {
481:     const column = Math.floor((point.x - left) / cellW);
482:     const row = Math.floor((point.y - top) / cellH);
483:     state.hoveredCell = game.isCellInBounds(row, column) ? { row, column } : null;
484:   } else {
485:     state.hoveredCell = null;
486:   }
487: }
