489: function showCardError(type, reason) {
490:   const name = PLANT_TYPES[type]?.name ?? "Planta";
491:   if (reason === "sun") setMessage(`No hay soles suficientes para ${name}.`);
492:   else if (reason === "cooldown") setMessage("La tarjeta todavía está recargando.");
493:   else if (reason === "occupied") setMessage("Esa casilla ya está ocupada.");
494:   else if (reason === "outside") setMessage("Coloca la planta dentro del tablero.");
495: }
