497: function handlePointerUp(event) {
498:   if (pointer.down !== event.button) return;
499:   const button = pointer.down;
500:   pointer.down = null;
501:   const point = canvasPoint(event); updatePointer(point);
502:   if (button === 2) {
503:     const plant = state.hoveredCell && game.getAt(state.hoveredCell.row, state.hoveredCell.column);
504:     if (plant && game.remove(plant.id)) setMessage(`Retirando ${plant.name.toLowerCase()}…`);
505:     return;
506:   }
507:   if (button !== 0) return;
508:   if (pointer.hoveredSun) {
509:     const collected = suns.collect(pointer.hoveredSun, performance.now());
510:     if (collected) {
511:       resources.add(SUN_CONFIG.value, "sun-pickup");
512:       setMessage(`¡+${SUN_CONFIG.value} soles!`, 1100);
513:     }
514:     pointer.hoveredSun = null;
515:     return;
516:   }
517:   const { x, y, w, h } = layout.card;
518:   if (point.x >= x && point.x <= x + w && point.y >= y && point.y <= y + h) {
519:     const type = "peashooter";
520:     if (state.selected === type) {
521:       state.selected = null;
522:       setMessage("Selección cancelada.");
523:       return;
524:     }
525:     const reason = game.canPlace(type, 0, 0).reason;
526:     if (!resources.canBuyPlant(PLANT_TYPES[type].cost)) {
527:       showCardError(type, "sun"); state.selected = null; return;
528:     }
529:     if (game.cooldownRemaining(type) > 0) {
530:       showCardError(type, "cooldown"); state.selected = null; return;
531:     }
532:     state.selected = type;
533:     setMessage("Lanzaguisantes elegida: apunta a una casilla libre.");
534:     return;
535:   }
536:   if (!state.hoveredCell) {
537:     if (state.selected) setMessage("Elige una casilla dentro del tablero.");
538:     return;
539:   }
540:   if (!state.selected) {
541:     if (game.getAt(state.hoveredCell.row, state.hoveredCell.column)) setMessage("Esta casilla ya está ocupada.");
542:     return;
543:   }
544:   const cell = state.hoveredCell;
545:   const { left, top, cellW, cellH } = layout;
546:   const worldPosition = {
547:     x: left + (cell.column + .5) * cellW,
548:     y: top + (cell.row + .87) * cellH,
549:   };
550:   const result = game.place(state.selected, cell.row, cell.column, worldPosition);
551:   if (!result.ok) { showCardError(state.selected, result.reason); return; }
552:   state.selected = null;
553:   setMessage(`¡${result.plant.name} plantada!  −${result.plant.cost} soles.`);
554: }
