556: function draw(time) {
557:   game.update(time);
558:   const activePlants = [...game.plants.values()].filter((plant) => plant.alive && plant.exists);
559:   for (const plant of activePlants) plant.boardX = (plant.worldPosition.x - layout.left) / layout.cellW;
560:   enemies.update(time, activePlants, game, layout.cellW);
561:   updateCombat(time);
562:   suns.update(time, { left: layout.left + SUN_CONFIG.radius + 3, top: layout.top + 6, width: Math.max(1, layout.boardW - (SUN_CONFIG.radius + 6) * 2), height: Math.max(1, layout.boardH - 12) });
563:   drawBackground(time);
564:   drawBrand(time);
565:   drawCard(time);
566:   drawCounter(time);
567:   drawBoard(time);
568:   drawSuns(time);
569:   drawFooter(time);
570:   requestAnimationFrame(draw);
571: }
