31:     if (!this.isCellInBounds(row, column)) return null;
32:     const id = this.occupancy[row][column];
33:     return id ? this.getPlant(id) : null;
34:   }
35:   isCellInBounds(row, column) {
36:     return Number.isInteger(row) && Number.isInteger(column) &&
37:       row >= 0 && row < this.rows && column >= 0 && column < this.columns;
38:   }
39:   cooldownRemaining(type, now = performance.now()) {
40:     return Math.max(0, (this.cardReadyAt.get(type) ?? 0) - now);
41:   }
42:   canPlace(type, row, column, now = performance.now()) {
43:     const definition = PLANT_TYPES[type];
44:     if (!definition || !this.isCellInBounds(row, column)) return { ok: false, reason: "outside" };
45:     if (this.occupancy[row][column]) return { ok: false, reason: "occupied" };
46:     if (!this.resources.canBuyPlant(definition.cost)) return { ok: false, reason: "sun" };
47:     if (this.cooldownRemaining(type, now) > 0) return { ok: false, reason: "cooldown" };
48:     return { ok: true };
49:   }
50:   place(type, row, column, worldPosition, now = performance.now()) {
51:     const check = this.canPlace(type, row, column, now);
52:     if (!check.ok) return check;
53:     const definition = PLANT_TYPES[type];
54:     if (!this.resources.spend(definition.cost, `plant:${type}`)) return { ok: false, reason: "sun" };
55:     const id = `plant-${this.nextId++}`;
56:     const plant = {
57:       id,
58:       type,
59:       name: definition.name,
60:       cost: definition.cost,
61:       maxHealth: definition.health,
62:       health: definition.health,
63:       alive: true,
64:       damage: definition.damage,
65:       attackIntervalMs: definition.attackIntervalMs,
66:       projectileSpeed: definition.projectileSpeed,
67:       attackState: "IDLE",
68:       targetId: null,
69:       nextAttackAt: now,
70:       attackStartedAt: 0,
71:       row,
72:       column,
73:       worldPosition: { x: worldPosition.x, y: worldPosition.y },
74:       exists: true,
75:       animationState: "placing",
76:       animationStartedAt: now,
77:       rechargeMs: definition.rechargeMs,
78:     };
79:     this.occupancy[row][column] = id;
80:     this.plants.set(id, plant);
81:     this.cardReadyAt.set(type, now + definition.rechargeMs);
82:     return { ok: true, plant };
83:   }
84:   /** Starts the death animation and frees the board cell immediately. */
85:   remove(id, now = performance.now()) {
86:     const plant = this.getPlant(id);
87:     if (!plant || !plant.alive || plant.animationState === "disappearing") return false;
88:     plant.alive = false;
89:     plant.animationState = "disappearing";
90:     plant.animationStartedAt = now;
91:     plant.attackState = "IDLE";
92:     plant.targetId = null;
93:     if (this.occupancy[plant.row][plant.column] === id) this.occupancy[plant.row][plant.column] = null;
94:     return true;
95:   }
96:   damage(id, amount, now = performance.now()) {
97:     const plant = this.getPlant(id);
98:     if (!plant || !plant.alive) return false;
99:     plant.health = Math.max(0, plant.health - Math.max(0, amount));
100:     plant.hitAt = now;
101:     if (plant.health === 0) this.remove(id, now);
102:     return true;
103:   }
104:   update(now = performance.now()) {
105:     for (const [id, plant] of this.plants) {
106:       const age = now - plant.animationStartedAt;
107:       if (plant.animationState === "placing" && age >= 460) plant.animationState = "idle";
108:       if (plant.animationState === "disappearing" && age >= 360) {
109:         plant.exists = false;
110:         if (this.occupancy[plant.row][plant.column] === id) this.occupancy[plant.row][plant.column] = null;
111:         this.plants.delete(id);
112:       }
113:     }
114:   }
115: }
